package com.vandorlabs.neoforge.propulsion;
import com.google.gson.*;
import com.vandorlabs.propulsion.PropulsionMaterial;
import java.nio.file.*;
/** Actual Source wrapper bytes, including every extended field. */
public final class PropulsionMaterialChecks {
 public static void main(String[] args)throws Exception{int cases=0,fields=0;try(var lines=Files.lines(Path.of(args[0]))){for(String line:(Iterable<String>)lines::iterator){JsonObject r=JsonParser.parseString(line).getAsJsonObject();String name=r.get("sprite").getAsString();int choice=r.get("choice").getAsInt(),brightness=r.get("brightness").getAsInt(),stride=r.get("stride").getAsInt(),uv=r.get("uv").getAsInt(),color=r.get("color").getAsInt();boolean identity=choice==9&&brightness==15,replace=PropulsionMaterial.housing(name)&&choice!=9;if(identity!=r.get("identity").getAsBoolean()||replace!=r.get("target").getAsBoolean())throw new AssertionError("Source material identity");JsonArray source=r.getAsJsonArray("sourceExtent"),target=r.getAsJsonArray(replace?"targetExtent":"sourceExtent"),input=r.getAsJsonArray("input"),output=r.getAsJsonArray("output");int[] data=new int[input.size()];for(int i=0;i<data.length;i++)data[i]=input.get(i).getAsInt();if(!identity)for(int v=0;v<4;v++){int at=v*stride;if(brightness<15&&PropulsionMaterial.emitter(name))data[at+color]=PropulsionMaterial.color(data[at+color],brightness);for(int axis=0;axis<2;axis++)data[at+uv+axis]=Float.floatToRawIntBits(PropulsionMaterial.remap(Float.intBitsToFloat(data[at+uv+axis]),source.get(axis*2).getAsFloat(),source.get(axis*2+1).getAsFloat(),target.get(axis*2).getAsFloat(),target.get(axis*2+1).getAsFloat()));}for(int i=0;i<data.length;i++){if(data[i]!=output.get(i).getAsInt())throw new AssertionError("Actual Source material byte "+cases+"/"+i);fields++;}cases++;}}if(cases!=960)throw new AssertionError("Coverage");System.out.println("Native propulsion material PASS cases="+cases+" fields="+fields+" exactSource ABGR/UV/trim/extendedpayload/fastpath");}
}
